{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "병역 복무 사유로 시·구청이 동물을 인수할 수 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제18조제1항제2호는 소유자등이 「병역법」에 따른 병역 복무를 하는 경우를 인수 사유로 정하고 있습니다. 같은 조 제1항 본문은 소유자등이 다른 방법으로는 정상적으로 동물을 사육하기 어려워 동물 인수신청서를 제출한 경우 시장 또는 구청장이 해당 동물을 인수할 수 있다고 규정하므로, 병역 복무로 다른 방법으로는 동물을 돌볼 수 없어 인수신청서를 낸 경우 시나 구청이 인수할 수 있습니다.",
          "b_ids": "동물보호:제18조제1항, 동물보호:제18조제1항제2호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "인수 후 보호를 희망하는 조례상 민간단체에 맡기고 경비를 지원할 수 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제18조제2항 본문은 시장 또는 구청장이 인수한 동물을 동물보호센터 등 적정한 시설에 보호조치하게 할 수 있다고 규정합니다. 같은 항 단서는 영 제6조에 따른 단체가 보호조치를 희망하는 경우 그 단체에 보호조치를 하게 할 수 있으며, 예산의 범위에서 필요한 경비를 지원할 수 있다고 정하고 있습니다. 따라서 인수 후 보호를 희망하는 조례상 민간단체가 있으면 그 단체에 맡기고 예산의 범위에서 경비를 지원할 수 있습니다.",
          "b_ids": "동물보호:제18조제2항, 동물보호:제18조제2항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
